// Verify HMAC signature from WP plugin (skip for manual ClickUp triggers).
const crypto = require('crypto');
const secret = $env.WPISTIC_HMAC_SECRET;
const headers = $input.first().json.headers || {};
const rawBody = $input.first().json.body;
const signature = headers['x-wpistic-signature'] || headers['X-Wpistic-Signature'];

// Manual triggers from ClickUp form skip HMAC (use API key instead).
if (!signature) {
  // Pass through; downstream auth check on ClickUp side.
  return $input.all();
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody))
  .digest('hex');

if (signature !== expected) {
  throw new Error('Invalid HMAC signature — request rejected.');
}

return $input.all();

// Idempotency guard — prevents duplicate runs.
// Uses workflow static data as a simple in-memory cache (24hr TTL).
// For production, swap to Redis via the Redis node.
const staticData = $getWorkflowStaticData('global');
staticData.seenRuns = staticData.seenRuns || {};

const body = $input.first().json.body || $input.first().json;
const runId = body.run_id;
const now = Date.now();
const TTL_MS = 24 * 60 * 60 * 1000;

// Clean expired entries
for (const k of Object.keys(staticData.seenRuns)) {
  if (now - staticData.seenRuns[k] > TTL_MS) delete staticData.seenRuns[k];
}

if (!runId) {
  throw new Error('Missing run_id — cannot dedupe.');
}

if (staticData.seenRuns[runId]) {
  // Already processed; return early signal
  return [{ json: { __skip: true, reason: 'duplicate run_id', run_id: runId } }];
}

staticData.seenRuns[runId] = now;
return [{ json: { ...body, __skip: false } }];

// WP post path: payload already contains full post data.
const d = $json;
return [{
  json: {
    run_id: d.run_id,
    source_type: 'wp_post',
    title: d.post.title,
    url: d.post.url,
    excerpt: d.post.excerpt,
    content_plain: d.post.content_plain,
    categories: d.post.categories || [],
    tags: d.post.tags || [],
    featured_image: d.post.featured_image || '',
    author: d.post.author?.display_name || 'Wordpressistic',
    site_url: d.site_url
  }
}];

