// Parse AI response and normalize to common shape
const d = $json;
const aiContent = d.choices?.[0]?.message?.content || '';
let parsed;
try {
  parsed = typeof aiContent === 'string' ? JSON.parse(aiContent) : aiContent;
} catch (e) {
  throw new Error('AI did not return valid JSON: ' + aiContent.slice(0, 200));
}

const input = $('Route by Trigger Type').item.json;
return [{
  json: {
    run_id: input.run_id,
    source_type: 'manual_topic',
    title: parsed.title,
    url: '',
    excerpt: parsed.excerpt || '',
    content_plain: parsed.content_plain || '',
    categories: [],
    tags: parsed.tags || [],
    featured_image: '',
    author: input.submitted_by || 'Wordpressistic',
    site_url: $env.WP_SITE_URL || 'https://wordpressistic.com'
  }
}];

// Take latest RSS item; mark source for attribution.
const input = $('Route by Trigger Type').item.json;
const items = $input.all();
if (!items.length) return [{ json: { __skip: true } }];
const latest = items[0].json;
return [{
  json: {
    run_id: input.run_id,
    source_type: 'rss_feed',
    title: latest.title,
    url: latest.link,
    excerpt: (latest.contentSnippet || '').slice(0, 280),
    content_plain: latest.content || latest.contentSnippet || '',
    categories: latest.categories || [],
    tags: [],
    featured_image: latest.enclosure?.url || '',
    author: latest.creator || 'Curated',
    site_url: input.feed_url,
    rss_attribution: latest.link
  }
}];

// Fan out: emit 8 items, one per platform, each carrying the full source content + the platform key.
const src = $json;
const platforms = ['linkedin', 'x', 'facebook', 'instagram', 'pinterest', 'gbp', 'medium', 'threads'];
return platforms.map(p => ({
  json: { ...src, platform: p }
}));

// Parse the AI response for this platform; attach metadata.
const d = $json;
const raw = d.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = { error: 'parse_failed', raw: raw.slice(0, 500) };
}

const src = $('Fan Out: 8 Platforms').item.json;
return [{
  json: {
    run_id: src.run_id,
    platform: src.platform,
    source_title: src.title,
    source_url: src.url,
    source_image: src.featured_image,
    variant: parsed,
    generated_at: new Date().toISOString()
  }
}];
